public async Task<Product> GetProductAsync(string id)
{
    var cached = await _redis.StringGetAsync(id);
    if (cached.HasValue)
    {
        return JsonSerializer.Deserialize<Product>(cached!);
    }

    var product = await _db.Products.FindAsync(id);
    if (product is not null)
    {
        await _redis.StringSetAsync(id,
            JsonSerializer.Serialize(product),
            expiry: TimeSpan.FromMinutes(5));
    }
    return product;
}

public async Task UpdateProductAsync(Product updated)
{
    await _db.SaveChangesAsync();
    await _redis.KeyDeleteAsync(updated.Id.ToString());
    // Force next read to repopulate from DB
}
